/** Lower authored view blocks and serialize registered relation views. */
import { encodePattern, encodeWhereOp, PatternVariables, queryRefOf } from "./pattern-encoding.js";
function encodeViewOp(op, vars) {
    if (op.op === "count") {
        return {
            op: "count",
            query: queryRefOf(op.query),
            in: encodePattern(op.in, vars),
            out: vars.nameOf(op.out),
        };
    }
    return encodeWhereOp(op, vars);
}
export function lowerRelationBlocks(named, alternatives) {
    const vars = new PatternVariables();
    for (const [variable, name] of named)
        vars.nameAs(variable, name);
    return alternatives.map((block) => block.map((op) => encodeViewOp(op, vars)));
}
/** Serialize one view: the registered alternatives already are IR. */
export function serializeView(ref, authored) {
    return {
        name: ref.viewName,
        ...(authored === undefined ? {} : { authored }),
        alternatives: ref.alternatives,
        ins: [...ref.ins],
        outs: [...ref.outs],
        bindings: [...ref.bindings],
        ...(ref.promise !== undefined ? { promise: ref.promise } : {}),
        ...(ref.holdsPredicate ? { holds: true } : {}),
    };
}
/** Whether a registered read operation names a view. */
export function viewLineIR(op) {
    return ((op.op === "find" || op.op === "whether" || op.op === "no") &&
        "view" in op &&
        typeof op.view === "string");
}
